```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

interface ListenerEntry {
  fn: Listener
  once: boolean
}

export function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, ListenerEntry[]>()

  const getListeners = (event: string): ListenerEntry[] => {
    const list = listenersMap.get(event)
    if (!list) {
      const newList: ListenerEntry[] = []
      listenersMap.set(event, newList)
      return newList
    }
    return list
  }

  return {
    on(event: string, listener: Listener): number {
      const list = getListeners(event)
      list.push({ fn: listener, once: false })
      return list.length
    },
    once(event: string, listener: Listener): number {
      const list = getListeners(event)
      list.push({ fn: listener, once: true })
      return list.length
    },
    off(event: string, listener: Listener): boolean {
      const list = listenersMap.get(event)
      if (!list) return false
      const index = list.findIndex((entry) => entry.fn === listener)
      if (index === -1) return false
      list.splice(index, 1)
      return true
    },
    emit(event: string, payload: unknown): unknown[] {
      const list = listenersMap.get(event)
      if (!list) return []

      const results: unknown[] = []
      const toRemoveIndices: number[] = []

      for (let i = 0; i < list.length; i++) {
        const entry = list[i]
        const result = entry.fn(payload)
        results.push(result)
        if (entry.once) {
          toRemoveIndices.push(i)
        }
      }

      // Remove from end to beginning to preserve indices during splicing
      toRemoveIndices.reverse()
      for (const index of toRemoveIndices) {
        list.splice(index, 1)
      }

      return results
    },
    listenerCount(event: string): number {
      const list = listenersMap.get(event)
      return list ? list.length : 0
    }
  }
}
