export function createRateLimiter(): {
  allow: (key: string, nowMs: number) => boolean;
  reset: (key: string) => void;
} {
  const WINDOW_SIZE_MS = 1000;
  const MAX_REQUESTS = 3;

  const state = new Map<
    string,
    { windowIndex: number; count: number }
  >();

  return {
    allow: (key, nowMs) => {
      const windowIndex = Math.floor(nowMs / WINDOW_SIZE_MS);
      const currentState = state.get(key);

      if (!currentState || currentState.windowIndex !== windowIndex) {
        state.set(key, { windowIndex, count: 1 });
        return true;
      }

      if (currentState.count < MAX_REQUESTS) {
        currentState.count++;
        return true;
      }

      return false;
    },

    reset: (key) => {
      state.delete(key);
    },
  };
}
