export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      cache.set(key, {
        value,
        expiresAt: nowMs + ttlMs
      });
    },
    get(key, nowMs) {
      const entry = cache.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },
    has(key, nowMs) {
      const entry = cache.get(key);
      if (!entry) {
        return false;
      }
      return nowMs < entry.expiresAt;
    },
    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const entry of cache.values()) {
        if (entry.expiresAt > nowMs) {
          count++;
        }
      }
      return count;
    },
    clear() {
      cache.clear();
    }
  };
}
