```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const events = new Map<string, Listener[]>();

  return {
    on(event, listener) {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const list = events.get(event)!;
      list.push(listener);
      return list.length;
    },
    once(event, listener) {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const list = events.get(event)!;
      const onceListener: Listener = (payload) => {
        listener(payload);
        const index = list.indexOf(onceListener);
        if (index !== -1) {
          list.splice(index, 1);
        }
      };
      list.push(onceListener);
      return list.length;
    },
    off(event, listener) {
      const list = events.get(event);
      if (!list) return false;
      const index = list.indexOf(listener);
      if (index !== -1) {
        list.splice(index, 1);
        return true;
      }
      return false;
    },
    emit(event, payload) {
      const list = events.get(event);
      if (!list) return [];
      const results: unknown[] = [];
      for (const l of list) {
        results.push(l(payload));
      }
      return results;
    },
    listenerCount(event) {
      const list = events.get(event);
      return list ? list.length : 0;
    }
  };
}
