```typescript
interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

const limit = 3;
const windowMs = 1000;

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const existing = state.get(key);
      if (!existing) {
        state.set(key, { windowStart: nowMs, count: 0 });
      } else {
        if (nowMs - existing.windowStart >= windowMs) {
          existing.windowStart = nowMs;
          existing.count = 0;
        }
      }

      const entry = state.get(key)!;
      if (entry.count < limit) {
        entry.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const entry = state.get(key);
      if (!entry) {
        return limit;
      }
      if (nowMs - entry.windowStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.count = 0;
        return limit;
      }
      return Math.max(0, limit - entry.count);
    },
    reset(key: string): void {
      state.delete(key);
    }
  };
}
