type Listener = (...args: any[]) => any;

interface EventEmitter {
  on(event: string, listener: Listener): () => void;
  once(event: string, listener: Listener): () => void;
  off(event: string, listener: Listener): void;
  emit(event: string, ...args: any[]): any[];
}

interface EventEntry {
  listener: Listener;
  once: boolean;
}

export function createEventEmitter(): EventEmitter {
  const eventMap = new Map<string, EventEntry[]>();

  function on(event: string, listener: Listener): () => void {
    if (!eventMap.has(event)) {
      eventMap.set(event, []);
    }
    const entries = eventMap.get(event)!;
    entries.push({ listener, once: false });
    return () => off(event, listener);
  }

  function once(event: string, listener: Listener): () => void {
    if (!eventMap.has(event)) {
      eventMap.set(event, []);
    }
    const entries = eventMap.get(event)!;
    entries.push({ listener, once: true });
    return () => off(event, listener);
  }

  function off(event: string, listener: Listener): void {
    if (!eventMap.has(event)) {
      return;
    }
    const entries = eventMap.get(event)!;
    const index = entries.findIndex(entry => entry.listener === listener);
    if (index !== -1) {
      entries.splice(index, 1);
      if (entries.length === 0) {
        eventMap.delete(event);
      }
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const results: any[] = [];
    const entries = eventMap.get(event);
    if (!entries) {
      return results;
    }

    const entriesToExecute = [...entries];
    const oneTimeIndices: number[] = [];

    for (let i = entriesToExecute.length - 1; i >= 0; i--) {
      const entry = entriesToExecute[i];
      if (entry.once) {
        oneTimeIndices.push(i);
      }
      results.push(entry.listener(...args));
    }

    for (const i of oneTimeIndices) {
      entries.splice(i, 1);
    }

    if (entries.length === 0) {
      eventMap.delete(event);
    }

    return results;
  }

  return { on, once, off, emit };
}
