```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, Array<{ listener: Listener; once: boolean }>>()

  function ensureEvent(event: string): Array<{ listener: Listener; once: boolean }> {
    if (!listenersMap.has(event)) {
      listenersMap.set(event, [])
    }
    return listenersMap.get(event)!
  }

  return {
    on(event, listener) {
      ensureEvent(event).push({ listener, once: false })
      return listenersMap.get(event)!.length
    },

    once(event, listener) {
      ensureEvent(event).push({ listener, once: true })
      return listenersMap.get(event)!.length
    },

    off(event, listener) {
      const list = listenersMap.get(event)
      if (!list) return false

      const index = list.findIndex(item => item.listener === listener)
      if (index === -1) return false

      list.splice(index, 1)
      return true
    },

    emit(event, payload) {
      const list = listenersMap.get(event)
      if (!list) return []

      const results: unknown[] = []
      const onceIndices: number[] = []

      for (let i = 0; i < list.length; i++) {
        const { listener, once } = list[i]
        const result = listener(payload)
        results.push(result)
        if (once) {
          onceIndices.push(i)
        }
      }

      for (let j = onceIndices.length - 1; j >= 0; j--) {
        list.splice(onceIndices[j], 1)
      }

      return results
    },

    listenerCount(event) {
      return listenersMap.get(event)?.length ?? 0
    }
  }
}
