export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { windowStart: number; count: number }>();

  interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
  }

  function getCurrentWindow(key: string, nowMs: number): { windowStart: number; count: number } {
    const current = state.get(key);
    if (!current || nowMs - current.windowStart >= windowMs) {
      return { windowStart: nowMs, count: 0 };
    }
    return current;
  }

  return {
    allow(key, nowMs) {
      const current = getCurrentWindow(key, nowMs);
      const remaining = limit - current.count;
      if (remaining <= 0) {
        return false;
      }
      current.count++;
      state.set(key, current);
      return true;
    },

    remaining(key, nowMs) {
      const current = getCurrentWindow(key, nowMs);
      const val = limit - current.count;
      return val < 0 ? 0 : val;
    },

    reset(key) {
      state.delete(key);
    }
  };
}
