const WINDOW_MS = 1000;
const MAX_REQUESTS = 3;

function createRateLimiter(): RateLimiter {
  const windows = new Map<string, { count: number; windowStart: number }>();

  return {
    isAllowed(key: string, nowMs: number): boolean {
      const windowInfo = windows.get(key);
      const windowEnd = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS + WINDOW_MS;

      if (!windowInfo || windowInfo.windowStart < windowEnd - WINDOW_MS + 1) {
        const currentWindowStart = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;
        if (windowInfo && windowInfo.windowStart === currentWindowStart) {
          windowInfo.count = 1;
          const result = 1 <= MAX_REQUESTS;
          if (!result) {
            windows.delete(key);
          }
          return result;
        }
        windows.set(key, { count: 1, windowStart: currentWindowStart });
        return true;
      }

      if (windowInfo.count < MAX_REQUESTS) {
        windowInfo.count++;
        return true;
      }

      return false;
    },

    reset(key: string): void {
      windows.delete(key);
    },
  };
}

export { createRateLimiter };
