interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

type KeyState = {
  windowStart: number
  used: number
}

function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<string, KeyState>()

  return {
    allow(key: string, nowMs: number): boolean {
      let keyState = state.get(key)

      // Check if we need to start a fresh window
      if (!keyState || (nowMs - keyState.windowStart) >= windowMs) {
        keyState = { windowStart: nowMs, used: 0 }
        state.set(key, keyState)
      }

      if (keyState.used < limit) {
        keyState.used++
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      let keyState = state.get(key)

      // Check if we need to start a fresh window
      if (!keyState || (nowMs - keyState.windowStart) >= windowMs) {
        return limit
      }

      return Math.max(0, limit - keyState.used)
    },

    reset(key: string): void {
      state.delete(key)
    }
  }
}

export { createRateLimiter }
