    listCompleted() {
      return todos.filter(todo => todo.completed);
    },

    listPending() {
      return todos.filter(todo => !todo.completed);
    },

    clearCompleted() {
      todos.length = 0;
      todos.push(...todos.filter(todo => !todo.completed));
