  let nextId = 1
  const todos = new Map<number, Todo>()

  return {
    addTodo(text: string): Todo {
      const id = nextId++
      const todo: Todo = { id, text, completed: false }
      todos.set(id, todo)
      return todo
    },
    getTodo(id: number): Todo | undefined {
      return todos.get(id)
    },
    toggleTodo(id: number): void {
      const todo = todos.get(id)
      if (todo) {
        todos.set(id, { ...todo, completed: !todo.completed })
      }
    },
    deleteTodo(id: number): boolean {
      const existed = todos.has(id)
      todos.delete(id)
      return existed
    },
    listTodos(): Todo[] {
      return Array.from(todos.values())
    },
    listCompleted(): Todo[] {
      const result: Todo[] = []
      for (const todo of todos.values()) {
        if (todo.completed) {
          result.push(todo)
        }
      }
      return result
    },
    listPending(): Todo[] {
      const result: Todo[] = []
      for (const todo of todos.values()) {
        if (!todo.completed) {
          result.push(todo)
        }
      }
      return result
    },
    clearCompleted(): void {
      const completedIds: number[] = []
      for (const [id, todo] of todos.entries()) {
        if (todo.completed) {
          completedIds.push(id)
        }
      }
      for (const id of completedIds) {
        todos.delete(id)
      }
    },
  }
}

interface Todo {
  id: number
  text: string
  completed: boolean
