  >();

  return {
    on(event: string, listener: Function): void {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ fn: listener, once: false });
    },

    once(event: string, listener: Function): void {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ fn: listener, once: true });
    },

    off(event: string, listener: Function): void {
      const list = listeners.get(event);
      if (list) {
        const index = list.findIndex((item) => item.fn === listener);
        if (index !== -1) {
          list.splice(index, 1);
        }
      }
    },

    emit(event: string, ...args: any[]): any[] {
      const list = listeners.get(event);
      const results: any[] = [];

      if (list) {
        const toRemove: number[] = [];

        for (let i = 0; i < list.length; i++) {
          const { fn, once } = list[i];
          const result = fn(...args);
          results.push(result);

          if (once) {
            toRemove.push(i);
          }
        }

        toRemove.reverse();
        toRemove.forEach((index) => list.splice(index, 1));
      }

      return results;
    },
