type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>()

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ listener, once: false })
      return listeners.get(event)!.length
    },

    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ listener, once: true })
      return listeners.get(event)!.length
    },

    off(event, targetListener) {
      const eventListeners = listeners.get(event)
      if (!eventListeners) {
        return false
      }
      const index = eventListeners.findIndex(item => item.listener === targetListener)
      if (index === -1) {
        return false
      }
      eventListeners.splice(index, 1)
      return true
    },

    emit(event, payload) {
      const eventListeners = listeners.get(event)
      if (!eventListeners) {
        return []
      }
      const snapshot = eventListeners.filter(item => item.listener !== null).slice()
      const results: unknown[] = []
      const toRemove: number[] = []

      for (let i = 0; i < snapshot.length; i++) {
        const item = snapshot[i]
        const originalIndex = eventListeners.findIndex(e => e === item)
        if (originalIndex === -1) {
          continue
        }
        results.push(item.listener(payload))
        if (item.once) {
          toRemove.push(originalIndex)
        }
      }

      for (let i = toRemove.length - 1; i >= 0; i--) {
        eventListeners.splice(toRemove[i], 1)
      }

      return results
    },

    listenerCount(event) {
      const eventListeners = listeners.get(event)
      return eventListeners ? eventListeners.length : 0
    }
  }
}
