export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<string, { windowStart: number; count: number }>()

  function allow(key: string, nowMs: number): boolean {
    let entry = state.get(key)

    if (!entry || nowMs - entry.windowStart >= windowMs) {
      entry = { windowStart: nowMs, count: 0 }
      state.set(key, entry)
    }

    if (entry.count < limit) {
      entry.count++
      return true
    }
    return false
  }

  function remaining(key: string, nowMs: number): number {
    const entry = state.get(key)

    if (!entry || nowMs - entry.windowStart >= windowMs) {
      return limit
    }

    const res = limit - entry.count
    return res < 0 ? 0 : res
  }

  function reset(key: string): void {
    state.delete(key)
  }

  return { allow, remaining, reset }
}
