export function createRateLimiter() {
  const windows = new Map<string, { windowStart: number; requestCount: number }>();
  const MAX_REQUESTS_PER_WINDOW = 3;
  const WINDOW_MS = 1000;

  function checkRateLimit(key: string, nowMs: number): boolean {
    const state = windows.get(key);

    if (!state || nowMs >= state.windowStart + WINDOW_MS) {
      windows.set(key, { windowStart: nowMs, requestCount: 1 });
      return true;
    }

    if (state.requestCount < MAX_REQUESTS_PER_WINDOW) {
      state.requestCount++;
      return true;
    }

    return false;
  }

  function reset(key: string): void {
    windows.delete(key);
  }

  function getRemaining(key: string, nowMs: number): number {
    const state = windows.get(key);

    if (!state || nowMs >= state.windowStart + WINDOW_MS) {
      return MAX_REQUESTS_PER_WINDOW;
    }

    return MAX_REQUESTS_PER_WINDOW - state.requestCount;
  }

  return {
    checkRateLimit,
    reset,
    getRemaining,
  };
}
