interface CacheEntry {
  value: unknown
  expiresAt: number
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

function isExpired(expiresAt: number, nowMs: number): boolean {
  return nowMs >= expiresAt
}

export function createTtlCache(): TtlCache {
  const entries = new Map<string, CacheEntry>()

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs !== undefined ? ttlMs : 1000
      const expiresAt = ttl > 0 ? nowMs + ttl : 0
      entries.set(key, { value, expiresAt })
    },
    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key)
      if (!entry) return undefined
      if (isExpired(entry.expiresAt, nowMs)) {
        entries.delete(key)
        return undefined
      }
      return entry.value
    },
    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key)
      if (!entry) return false
      if (isExpired(entry.expiresAt, nowMs)) {
        entries.delete(key)
        return false
      }
      return true
    },
    delete(key: string): boolean {
      return entries.delete(key)
    },
    size(nowMs: number): number {
      let count = 0
      for (const entry of entries.values()) {
        if (!isExpired(entry.expiresAt, nowMs)) {
          count++
        }
      }
      return count
    },
    clear(): void {
      entries.clear()
    }
  }
}
